<!DOCTYPE html>
<html lang="zh">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>三字经 - 历史篇</title>
<script type="text/javascript" id="MathJax-script" async
  src="https://cdn.jsdelivr.net/npm/mathjax@3/es5/tex-mml-chtml.js">
</script>
<style>
  body {
    background: #cfd8dc;
    margin: 0;
    padding: 20px;
    font-family: "STSong", "SimSun", serif;
    display: flex;
    justify-content: center;
  }
  .page {
    background: #fdfdf8;
    width: 700px;
    padding: 25px 15px;
    position: relative;
    box-shadow: 0 0 8px rgba(0,0,0,0.3);
    display: flex;
  }
  .border-col {
    width: 20px;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    align-items: center;
  }
  .border-bar {
    width: 6px;
    height: 45%;
    background: repeating-linear-gradient(
      to bottom,
      #111 0px,
      #111 2px,
      transparent 2px,
      transparent 4px
    );
  }
  .flower {
    width: 40px;
    height: 40px;
    border-radius: 50%;
    border: 2px solid #111;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 10px;
    text-align: center;
    color: #111;
    background: radial-gradient(circle at center, #fff 0%, #eee 60%, #ccc 100%);
  }

  .content {
    flex: 1;
    padding: 0 15px;
    display: flex;
  }

  .main-text {
    flex: 1;
  }

  .row {
    display: flex;
    justify-content: space-between;
    margin-bottom: 10px;
  }

  .cell {
    text-align: center;
    width: 24%;
  }

  .pinyin {
    font-size: 10px;
    color: #333;
    letter-spacing: 1px;
    margin-bottom: 2px;
  }

  .hanzi {
    font-size: 20px;
    font-weight: bold;
    letter-spacing: 1px;
    color: #111;
  }

  .sidebar {
    width: 40px;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: space-between;
    border-left: 1px solid #333;
    padding-left: 8px;
    margin-left: 5px;
  }

  .side-title {
    writing-mode: vertical-rl;
    font-size: 16px;
    font-weight: bold;
    letter-spacing: 4px;
    margin-top: 10px;
  }

  .side-sub {
    writing-mode: vertical-rl;
    font-size: 12px;
    letter-spacing: 3px;
    margin-top: 15px;
    color: #333;
  }

  .page-num {
    writing-mode: vertical-rl;
    font-size: 16px;
    font-weight: bold;
    margin-bottom: 10px;
  }
</style>
</head>
<body>

<div class="page">

  <!-- Left decorative border -->
  <div class="border-col">
    <div class="border-bar"></div>
    <div class="border-bar"></div>
  </div>

  <div class="content">
    <div class="main-text">

      <div class="row">
        <div class="cell"><div class="pinyin">guāng wǔ xīng</div><div class="hanzi">光武兴，</div></div>
        <div class="cell"><div class="pinyin">wéi dōng hàn</div><div class="hanzi">为东汉。</div></div>
        <div class="cell"><div class="pinyin">sì bǎi nián</div><div class="hanzi">四百年，</div></div>
        <div class="cell"><div class="pinyin">zhōng yú xiàn</div><div class="hanzi">终于献。</div></div>
      </div>

      <div class="row">
        <div class="cell"><div class="pinyin">wèi shǔ wú</div><div class="hanzi">魏蜀吴，</div></div>
        <div class="cell"><div class="pinyin">zhēng hàn dǐng</div><div class="hanzi">争汉鼎。</div></div>
        <div class="cell"><div class="pinyin">hào sān guó</div><div class="hanzi">号三国，</div></div>
        <div class="cell"><div class="pinyin">qì liǎng jìn</div><div class="hanzi">迄两晋。</div></div>
      </div>

      <div class="row">
        <div class="cell"><div class="pinyin">sòng qí jì</div><div class="hanzi">宋齐继，</div></div>
        <div class="cell"><div class="pinyin">liáng chén chéng</div><div class="hanzi">梁陈承。</div></div>
        <div class="cell"><div class="pinyin">wéi nán cháo</div><div class="hanzi">为南朝，</div></div>
        <div class="cell"><div class="pinyin">dū jīn líng</div><div class="hanzi">都金陵。</div></div>
      </div>

      <div class="row">
        <div class="cell"><div class="pinyin">běi yuán wèi</div><div class="hanzi">北元魏，</div></div>
        <div class="cell"><div class="pinyin">fēn dōng xī</div><div class="hanzi">分东西。</div></div>
        <div class="cell"><div class="pinyin">yǔ wén zhōu</div><div class="hanzi">宇文周，</div></div>
        <div class="cell"><div class="pinyin">yǔ gāo qí</div><div class="hanzi">与高齐。</div></div>
      </div>

      <div class="row">
        <div class="cell"><div class="pinyin">dài zhì suí</div><div class="hanzi">迨至隋，</div></div>
        <div class="cell"><div class="pinyin">yī tǔ yǔ</div><div class="hanzi">一土宇。</div></div>
        <div class="cell"><div class="pinyin">bù zài chuán</div><div class="hanzi">不再传，</div></div>
        <div class="cell"><div class="pinyin">shī tǒng xù</div><div class="hanzi">失统绪。</div></div>
      </div>

      <div class="row">
        <div class="cell"><div class="pinyin">táng gāo zǔ</div><div class="hanzi">唐高祖，</div></div>
        <div class="cell"><div class="pinyin">qǐ yì shī</div><div class="hanzi">起义师。</div></div>
        <div class="cell"><div class="pinyin">chú suí luàn</div><div class="hanzi">除隋乱，</div></div>
        <div class="cell"><div class="pinyin">chuàng guó jī</div><div class="hanzi">创国基。</div></div>
      </div>

      <div class="row">
        <div class="cell"><div class="pinyin">èr shí chuán</div><div class="hanzi">二十传，</div></div>
        <div class="cell"><div class="pinyin">sān bǎi zǎi</div><div class="hanzi">三百载。</div></div>
        <div class="cell"><div class="pinyin">liáng miè zhī</div><div class="hanzi">梁灭之，</div></div>
        <div class="cell"><div class="pinyin">guó nǎi gǎi</div><div class="hanzi">国乃改。</div></div>
      </div>

      <div class="row">
        <div class="cell"><div class="pinyin">liáng táng jìn</div><div class="hanzi">梁唐晋，</div></div>
        <div class="cell"><div class="pinyin">jí hàn zhōu</div><div class="hanzi">及汉周。</div></div>
        <div class="cell"><div class="pinyin">chēng wǔ dài</div><div class="hanzi">称五代，</div></div>
        <div class="cell"><div class="pinyin">jiē yǒu yóu</div><div class="hanzi">皆有由。</div></div>
      </div>

      <div class="row">
        <div class="cell"><div class="pinyin">yán sòng xīng</div><div class="hanzi">炎宋兴，</div></div>
        <div class="cell"><div class="pinyin">shòu zhōu shàn</div><div class="hanzi">受周禅。</div></div>
        <div class="cell"><div class="pinyin">shí bā chuán</div><div class="hanzi">十八传，</div></div>
        <div class="cell"><div class="pinyin">nán běi hùn</div><div class="hanzi">南北混。</div></div>
      </div>

      <div class="row">
        <div class="cell"><div class="pinyin">liáo yǔ jīn</div><div class="hanzi">辽与金，</div></div>
        <div class="cell"><div class="pinyin">dì hào fēn</div><div class="hanzi">帝号纷。</div></div>
        <div class="cell"><div class="pinyin">dài miè liáo</div><div class="hanzi">迨灭辽，</div></div>
        <div class="cell"><div class="pinyin">sòng yóu cún</div><div class="hanzi">宋犹存。</div></div>
      </div>

      <div class="row">
        <div class="cell"><div class="pinyin">zhì yuánxīng</div><div class="hanzi">至元兴，</div></div>
        <div class="cell"><div class="pinyin">jīn xù xiē</div><div class="hanzi">金绪歇。</div></div>
        <div class="cell"><div class="pinyin">yǒu sòng shì</div><div class="hanzi">有宋世，</div></div>
        <div class="cell"><div class="pinyin">yì tóng miè</div><div class="hanzi">一同灭。</div></div>
      </div>

      <div class="row">
        <div class="cell"><div class="pinyin">bìng zhōng guó</div><div class="hanzi">并中国，</div></div>
        <div class="cell"><div class="pinyin">jiān róng dí</div><div class="hanzi">兼戎狄。</div></div>
        <div class="cell"><div class="pinyin">jiǔ shí nián</div><div class="hanzi">九十年，</div></div>
        <div class="cell"><div class="pinyin">guó zuò fèi</div><div class="hanzi">国祚废。</div></div>
      </div>

      <div class="row">
        <div class="cell"><div class="pinyin">míng tài zǔ</div><div class="hanzi">明太祖，</div></div>
        <div class="cell"><div class="pinyin">jiǔ qīn shī</div><div class="hanzi">久亲师。</div></div>
        <div class="cell"><div class="pinyin">chuán jiàn wén</div><div class="hanzi">传建文，</div></div>
        <div class="cell"><div class="pinyin">fāng sì sì</div><div class="hanzi">方四祀。</div></div>
      </div>

      <div class="row">
        <div class="cell"><div class="pinyin">qiān běi jīng</div><div class="hanzi">迁北京，</div></div>
        <div class="cell"><div class="pinyin">yǒng lè sì</div><div class="hanzi">永乐嗣。</div></div>
        <div class="cell"><div class="pinyin">dài chóng zhēn</div><div class="hanzi">迨崇祯，</div></div>
        <div class="cell"><div class="pinyin">méi shān shì</div><div class="hanzi">煤山逝。</div></div>
      </div>

      <div class="row">
        <div class="cell"><div class="pinyin">qīng tài zǔ</div><div class="hanzi">清太祖，</div></div>
        <div class="cell"><div class="pinyin">yīng jǐng mìng</div><div class="hanzi">膺景命。</div></div>
        <div class="cell"><div class="pinyin">jìng sì fāng</div><div class="hanzi">靖四方，</div></div>
        <div class="cell"><div class="pinyin">kè dà dìng</div><div class="hanzi">克大定。</div></div>
      </div>

    </div>

    <!-- Vertical sidebar text -->
    <div class="sidebar">
      <div class="side-title">三字经</div>
      <div class="side-sub">国学君子吟<br>幸福家国兴</div>
      <div class="page-num">三</div>
    </div>
  </div>

  <!-- Right decorative border with flowers -->
  <div class="border-col">
    <div class="flower">[Icon:<br>flower]</div>
    <div class="border-bar"></div>
    <div class="border-bar"></div>
    <div class="flower">[Icon:<br>flower]</div>
  </div>

</div>

</body>
</html>
```
